// openConnection() TYLKO TWORZY obiekt polaczenia - nie laczy sie jeszcze!
// Dopiero wywolanie metody, ktora potrzebuje danych z serwera
// (np. getInputStream(), getHeaderFields()), wyzwala faktyczne polaczenie.

URI uri = new URI("http://localhost:" + port + "/hello");
URLConnection connection = uri.toURL().openConnection();

System.out.println(connection.getClass().getName());
// sun.net.www.protocol.http.HttpURLConnection - dla http(s)
// openConnection() zawsze zwraca konkretny podtyp HttpURLConnection

// getHeaderFields() - zwraca WSZYSTKIE naglowki jako
// Map<String, List<String>> (jeden naglowek moze miec wiele wartosci).
// Klucz null w tej mapie to specjalny wpis zawierajacy linie statusu
// (np. "HTTP/1.1 200 OK").

Map<String, List<String>> headers = connection.getHeaderFields();
headers.forEach((name, values) ->
        System.out.println((name == null ? "(status)" : name) + " = " + values));

// getHeaderField(name) - wygodny skrot do odczytu JEDNEJ (pierwszej)
// wartosci konkretnego naglowka
System.out.println(connection.getHeaderField("Content-Type"));

// getInputStream() zwraca strumien bajtow z trescia odpowiedzi.
// Warto opakowac go w BufferedReader dla wygodnego czytania tekstu.

StringBuilder body = new StringBuilder();
try (BufferedReader reader = new BufferedReader(
        new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8))) {
    String line;
    while ((line = reader.readLine()) != null) {
        body.append(line);
    }
}
System.out.println("Odebrana tresc: " + body);
